-- Datenbanktests der Beta. Bricht bei jedem Fehlschlag mit Fehler ab (Backlog A-4). Aufruf: psql -v ON_ERROR_STOP=1 -f …
create temp table r (name text, ok boolean);
grant all on r to authenticated, anon;
create function pg_temp.fails(q text) returns boolean language plpgsql as $$ begin execute q; return false; exception when others then return true; end $$;
grant execute on function pg_temp.fails(text) to authenticated, anon;
set role authenticated;
select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","aal":"aal2","role":"authenticated"}', false);
delete from app_documents where doc_key = 'checkins';
delete from app_documents where doc_key = 'koerper';
select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","aal":"aal1","role":"authenticated"}', false);
select set_config('request.jwt.claims', '{"sub":"22222222-2222-2222-2222-222222222222","aal":"aal2","role":"authenticated"}', false);
with d as (delete from app_documents returning 1) insert into r select 'anderer Nutzer kann nicht löschen', count(*) = 0 from d;
select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","aal":"aal2","role":"authenticated"}', false);
delete from beta_consents;
with d as (delete from app_documents returning 1) insert into r select 'nach Widerruf Löschen möglich', count(*) = 1 from d;
reset role;
set role anon;
select set_config('request.jwt.claims', '', false);
reset role;
delete from auth.users;
select (case when ok then 'ok   ' else 'FEHL ' end) || name from r;
do $$ declare f int; t int; begin select count(*) filter (where not ok), count(*) into f, t from r; raise notice '% von % Datenbanktests bestanden', t - f, t; if f > 0 then raise exception '% Datenbanktests fehlgeschlagen', f; end if; end $$;
